const CACHE_NAME="reverie-pwa-v33",PAGE_CACHE_NAME="reverie-pages-v33",STATIC_ASSETS=["/","/search","/entities","/uploads","/privacy","/tasks","/recommendations","/static/manifest.json","/static/reverie-home.min.css","/static/reverie-home.min.js","/static/reverie-list-page.min.css","/static/reverie-list-page.min.js","/static/reverie-search.min.js","/static/reverie-entities.min.js","/static/reverie-uploads.min.js","/static/reverie-capture.min.js","/static/reverie-shared.min.js","/static/logo_reverie.webp","/static/icon-192.png","/static/icon-512.png"];self.addEventListener("install",t=>{t.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(STATIC_ASSETS)).catch(()=>{})),self.skipWaiting()}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(e=>Promise.all(e.filter(i=>![CACHE_NAME,PAGE_CACHE_NAME].includes(i)).map(i=>caches.delete(i))))),self.clients.claim()}),self.addEventListener("fetch",t=>{const e=t.request;if(e.method!=="GET")return;const i=new URL(e.url);if(e.headers.get("X-Reverie-App-Shell")==="1"){t.respondWith(fetch(e));return}if(e.mode==="navigate"){t.respondWith(caches.open(PAGE_CACHE_NAME).then(n=>n.match(e).then(s=>{const a=fetch(e).then(r=>(r.ok&&n.put(e,r.clone()),r)).catch(()=>s||caches.match("/")||Response.error());return s||a})));return}i.origin!==self.location.origin||!i.pathname.startsWith("/static/")||t.respondWith(caches.match(e).then(n=>n||fetch(e).then(s=>{if(s.ok){const a=s.clone();caches.open(CACHE_NAME).then(r=>r.put(e,a))}return s})))});
